@section('content')<form method="POST" action="{{ route('procurement.conversions.store') }}">@csrf<div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table table-bordered table-sm align-middle text-center"><thead><tr><th>Size lông \ Size thịt</th>@foreach($processedSizes as $s)<th>{{ number_format($s,1) }}</th>@endforeach<th>Tổng</th></tr></thead><tbody>@foreach($liveSizes as $live)<tr data-rate-row><th>{{ number_format($live,1) }}</th>@foreach($processedSizes as $processed)@php $rate=$rates->get(number_format($live,1),collect())->first(fn($r)=>(float)$r->processed_size===(float)$processed); @endphp<td><input type="number" min="0" max="100" step=".001" name="rates[{{ $live }}][{{ $processed }}]" value="{{ $rate?->percentage ?? 0 }}" class="form-control form-control-sm text-center rate-input"></td>@endforeach<td class="fw-bold row-total">0%</td></tr>@endforeach</tbody></table></div><button class="btn btn-primary">Lưu ma trận tỷ lệ</button></div></div></form>
<div class="card border-0 shadow-sm mt-4"><div class="card-header bg-white"><strong>Tính thử sản lượng sơ chế</strong></div><div class="card-body"><div class="row g-2"><div class="col-md-3"><label>Số lượng vịt lông</label><input id="calcQuantity" type="number" value="1000" class="form-control"></div><div class="col-md-3"><label>Size vịt lông</label><select id="calcLiveSize" class="form-select">@foreach($liveSizes as $s)<option value="{{ $s }}">{{ number_format($s,1) }}</option>@endforeach</select></div><div class="col-md-2 align-self-end"><button type="button" id="calculateBtn" class="btn btn-warning w-100">Tính sản lượng</button></div></div><div id="conversionResult" class="mt-3"></div></div></div>@endsection
@push('scripts')<script>function sums(){document.querySelectorAll('[data-rate-row]').forEach(r=>{const s=[...r.querySelectorAll('.rate-input')].reduce((a,e)=>a+(+e.value||0),0);const t=r.querySelector('.row-total');t.textContent=s.toFixed(2)+'%';t.className='fw-bold row-total '+(s===0||Math.abs(s-100)<.01?'text-success':'text-danger')})}document.querySelectorAll('.rate-input').forEach(e=>e.addEventListener('input',sums));sums();document.getElementById('calculateBtn').onclick=()=>{const q=+document.getElementById('calcQuantity').value||0,l=document.getElementById('calcLiveSize').value,row=[...document.querySelectorAll('[data-rate-row]')].find(r=>r.querySelector('th').textContent.trim()===Number(l).toFixed(1));let h='<div class="row g-2">';if(row){[...row.querySelectorAll('.rate-input')].forEach(e=>{const size=e.name.match(/\[([^\]]+)\]$/)[1],pct=+e.value||0;if(pct>0)h+=`<div class="col-4 col-md-2"><div class="border rounded p-2"><small>Size ${size}</small><div class="fw-bold">${Math.round(q*pct/100)} con</div></div></div>`})}h+=`<div class="col-4 col-md-2"><div class="border rounded p-2"><small>Bộ lông</small><div class="fw-bold">${q}</div></div></div><div class="col-4 col-md-2"><div class="border rounded p-2"><small>Bộ lòng</small><div class="fw-bold">${q}</div></div></div></div>`;document.getElementById('conversionResult').innerHTML=h}</script>@endpush
